            545, 567, 540,
            540, 533, 545,
        };
        int faceCount = 6103;
        var pads = new[]
        {
            PadGrader.PadBoundary.CreatePlanar(
                new[]
                {
                    -5.712291854134824, 40.534236205426694, 11.864841188952315, -0.46143776569372136, 34.5509180907939, 11.864841188952315, -9.733674810555218, 26.413766963236124, 11.864841188952315, -14.98450069027585, 32.3970529407052, 11.864841188952315, -7.934646305766025, 38.58373969909954, 11.864841188952315, -9.134067687604276,
                    39.950196604046376, 11.864841188952315, -6.911266943681859, 41.90128243687725, 11.864841188952315,
                },
                7,
                5.502644302081554E-32,
                -3.8864248541680353E-32,
                11.864841188952314,
                33,
                0,
                stitchApronDistance: 0.5,
                fillSlopeAngleDeg: 33),
            PadGrader.PadBoundary.CreatePlanar(
                new[]
                {
                    -50.00060091977794, -4.670798584827002, 8.55000000000291, -45.48780498919474, -12.191994773750606, 8.55000000000291, -32.02439629272115, -4.1125079194493726, 8.55000000000291, -36.53669779728082, 3.407701277318095, 8.55000000000291,
                },
                4,
                -0,
                -0,
                8.55000000000291,
                33,
                0,
                stitchApronDistance: 0.5,
                fillSlopeAngleDeg: 33),
            PadGrader.PadBoundary.CreatePlanar(
                new[]
                {
                    -9.34125530519098, -3.090906273400016, 8, -2.2167870951286712, 1.9901580350859556, 8, -6.914624865261241, 8.577281089884014, 8, -14.03909307532355, 3.4962167813980427, 8,
                },
                4,
                0,
                0,
                8,
                33,
                0,
                stitchApronDistance: 0.5,
                fillSlopeAngleDeg: 33),
            PadGrader.PadBoundary.CreatePlanar(
                new[]
                {
                    37.24297072819117, 49.13491127625191, 9.428528231062414, 32.98905970191116, 52.71996084461901, 9.428528231062414, 22.316899999976155, 40.05669999856036, 9.428528231062414, 26.57081102625617, 36.471650430193264, 9.428528231062414,
                },
                4,
                0,
                0,
                9.428528231062414,
                33,
                0,
                stitchApronDistance: 0.5,
                fillSlopeAngleDeg: 33),
            PadGrader.PadBoundary.CreatePlanar(
                new[]
                {
                    10.280399999581274, 28.894200000795532, 9.06005208418408, 14.148740197284798, 23.227257926231488, 9.06005208418408, 22.914630365445262, 29.210986868574324, 9.06005208418408, 19.046290167741727, 34.87792894313837, 9.06005208418408,
                },
                4,
                -0,
                -0,
                9.06005208418408,
                33,
                0,
                stitchApronDistance: 0.5,
                fillSlopeAngleDeg: 33),
            PadGrader.PadBoundary.CreatePlanar(
                new[]
                {
                    45.63927574069193, 42.40859936601771, 5.8000000000000025, 34.540760808917284, 24.933698658790306, 5.8000000000000025, 19.10046654619766, 6.8413345086873205, 5.8000000000000025, 3.6707545754430297, -7.360976179837927, 5.8000000000000025, -5.719199547665567, -13.65422185913408, 5.8000000000000025, 5.429957248583095,
                    -21.160518534301175, 5.8000000000000025, 13.930596716876266, -17.959605268820454, 5.8000000000000025, 21.69373369935512, -19.139505030604308, 5.8000000000000025, 34.189299999736264, -7.468699999270041, 5.8000000000000025, 36.57129999995233, -4.799300000187954, 5.8000000000000025, 41.640100000426195, 3.8484999983338457,
                    5.8000000000000025, 46.65969999972733, 10.897100001457124, 5.8000000000000025, 61.67724818607488, 34.890980503426825, 5.8000000000000025, 65.69600000046194, 42.31419999897481, 5.8000000000000025, 73.59238318685786, 57.07046963935426, 5.8000000000000025, 76.93400000035763, 65.82649999856949, 5.8000000000000025,
                    84.13980000000447, 83.20549999922513, 5.8000000000000025, 70.76609999965876, 86.36800000071526, 5.8000000000000025, 60.15923627987368, 68.05896955011764, 5.8000000000000025, 50.68200000003, 50.348499998450194, 5.8000000000000025,
                },
                20,
                0,
                -1.0449162207618619E-32,
                5.800000000000001,
                33,
                0,
                stitchApronDistance: 0.5,
                fillSlopeAngleDeg: 33),
            PadGrader.PadBoundary.CreatePlanar(
                new[]
                {
                    45.930968981824975, 67.87109631626737, 10.16772812949064, 44.41704520148622, 68.66718012340401, 10.16772812949064, 42.757231160004864, 65.51060381275316, 10.16772812949064, 44.27115494034362, 64.71452000561656, 10.16772812949064,
                },
                4,
                0,
                0,
                10.16772812949064,
                33,
                0,
                stitchApronDistance: 0.5,
                fillSlopeAngleDeg: 33),
        };
        PadGrader.LockCurve[]? lockCurves = null;

        GradingResult? result = PadGrader.Grade(
            vertices,
            vertexCount,
            faces,
            faceCount,
            pads,
            lockCurves,
            out string? errorMessage,
            modelTolerance: 0.01);

        Assert.NotNull(result);

        // This 7-pad protected scene previously fell all the way through to the legacy whole-mesh
        // retriangulation fallback, which produced ~88 deg spikes against a 33 deg target. The
        // region-remesh tier must now catch it: watertight, spike-free, and NOT the legacy fallback.
        // (The dense multi-pad carve leaves tiny interior islands inside the merged hole; the tier
        // must treat those as islands to drop, not as holes that "contain no pad".)
        Assert.DoesNotContain(
            result!.Diagnostics,
            d => d.Contains("constrained whole-mesh retriangulation fallback", StringComparison.OrdinalIgnoreCase));
        Assert.Contains(
            result.Diagnostics,
            d => d.Contains("region remesh", StringComparison.OrdinalIgnoreCase));

        // Watertight + manifold + single boundary loop (same boundary topology as the input terrain).
        var inputTopo = MeshTopologyValidator.AnalyzeBoundaryGraph(faces, faceCount);
        var topo = MeshTopologyValidator.AnalyzeBoundaryGraph(result.Faces, result.FaceCount);
        Assert.Equal(0, topo.NonManifoldEdgeCount);
        Assert.False(topo.HasOpenBoundaryChains);
        Assert.Equal(inputTopo.BoundaryComponentCount, topo.BoundaryComponentCount);

        // The grading introduces no face steeper than the terrain's own natural relief. This input is
        // genuinely cliffy (source spot heights jump several units over <1 unit XY, so the terrain has
        // ~90 deg walls), so a fixed slope threshold cannot tell a grading spike apart from natural
        // terrain. The invariant that distinguishes the spike-free region-remesh tier from the legacy
        // whole-mesh fallback (which added ~88 deg batter spikes) is: the result's steepest face does
        // not exceed the input terrain's steepest face.
        double[] v = result.Vertices;
        double maxSlope = 0.0;
        for (int f = 0; f < result.FaceCount; f++)
        {
            int a = result.Faces[f * 3], b = result.Faces[f * 3 + 1], c = result.Faces[f * 3 + 2];
            double slope = FaceSlopeDeg(v, a, b, c);
            if (slope > maxSlope) maxSlope = slope;
        }

        double inputMaxSlope = 0.0;
        for (int f = 0; f < faceCount; f++)
        {
            int a = faces[f * 3], b = faces[f * 3 + 1], c = faces[f * 3 + 2];
            double slope = FaceSlopeDeg(vertices, a, b, c);
            if (slope > inputMaxSlope) inputMaxSlope = slope;
        }

        Assert.True(
            maxSlope <= inputMaxSlope + 0.5,
            $"Grading introduced a face ({maxSlope:F1} deg) steeper than the terrain's natural relief ({inputMaxSlope:F1} deg).");

        // Every pad — including the small ones in coarse terrain that previously carved no hole — is
        // flattened to its plane. Each pad must have at least one deep-interior vertex (>0.5 in from the
        // footprint edge) and all such vertices must sit on the pad plane.
        for (int pi = 0; pi < pads.Length; pi++)
        {
            var pad = pads[pi];
            double padZ = pad.EvaluateZ(pad.XyVertices[0], pad.XyVertices[1]);
            int interiorVerts = 0;
            var seen = new HashSet<int>();
            for (int f = 0; f < result.FaceCount; f++)
            {
                for (int k = 0; k < 3; k++)
                {
                    int idx = result.Faces[f * 3 + k];
                    if (!seen.Add(idx)) continue;
                    if (PadGrader.PointInPolygon(v[idx*3], v[idx*3+1], pad.XyVertices, pad.VertexCount) &&
                        PadGrader.DistToPolygon(v[idx*3], v[idx*3+1], pad.XyVertices, pad.VertexCount) > 0.5)
                    {
                        interiorVerts++;
                        Assert.True(
                            System.Math.Abs(v[idx*3+2] - padZ) < 0.1,
                            $"Pad {pi} interior vertex at ({v[idx*3]:F1},{v[idx*3+1]:F1}) is z={v[idx*3+2]:F2}, not the pad plane {padZ:F2}.");
                    }
                }
            }

            Assert.True(interiorVerts > 0, $"Pad {pi} has no flat interior vertex (was not flattened).");
        }
    }

    private static double FaceSlopeDeg(double[] v, int a, int b, int c)
    {
        double ax=v[a*3],ay=v[a*3+1],az=v[a*3+2];
        double bx=v[b*3],by=v[b*3+1],bz=v[b*3+2];
        double cx=v[c*3],cy=v[c*3+1],cz=v[c*3+2];
        double ux=bx-ax,uy=by-ay,uz=bz-az,wx=cx-ax,wy=cy-ay,wz=cz-az;
        double nx=uy*wz-uz*wy,ny=uz*wx-ux*wz,nz=ux*wy-uy*wx;
        double len=Math.Sqrt(nx*nx+ny*ny+nz*nz);
        if(len<1e-12) return 0.0;
        return Math.Acos(Math.Min(1.0,Math.Abs(nz)/len))*180.0/Math.PI;
    }
